    with open('data/glove.6B.{}d.txt'.format(glv_size),'r') as fp:
        for line in fp:
            # Skip Git LFS pointer lines
            if line.startswith('version') or line.startswith('oid') or line.startswith('size'):
                continue
            word, *vec = line.split()
            try:
                glv[word] = torch.tensor(list(map(float , vec)))
            except ValueError:
                # Skip lines that can't be parsed as embeddings
